import { lazy } from 'react';
import { Building2 as IcBuilding2, CircleUser as IcCircleUser, Contact as IcContact, HeartPulse as IcHeartPulse, Users as IcUsers } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Customers — hub page for the CRM menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 4 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'CRMCustomers'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const Accounts = lazy(() => import('./Accounts'));
const Contacts = lazy(() => import('./Contacts'));
const Customer360 = lazy(() => import('./Customer360'));
const CustomerHealthDashboard = lazy(() => import('./CustomerHealthDashboard'));

export const TABS = [
  { id: 'accounts', label: 'Accounts', icon: IcBuilding2, page: 'Accounts', Component: Accounts },
  { id: 'contacts', label: 'Contacts', icon: IcContact, page: 'Contacts', Component: Contacts },
  { id: 'c360', label: 'Customer 360', icon: IcCircleUser, page: 'Customer360', Component: Customer360 },
  { id: 'health', label: 'Health Engine', icon: IcHeartPulse, page: 'CustomerHealthDashboard', Component: CustomerHealthDashboard },
];

export default function CRMCustomers({ setPage }) {
  return (
    <TabHub
      icon={IcUsers}
      eyebrow="CRM"
      title="Customers"
      subtitle="Accounts, contacts, the 360° record and the health engine"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
